import java.util.*;

public class Main {
    /** 用一个定长槽位模型对比三种 GC 算法：碎片数、是否移动、空间浪费。 */
    static final int SLOTS = 12;

    static int holes(boolean[] used) {
        int h = 0; boolean inHole = false;
        for (boolean u : used) {
            if (!u && !inHole) { h++; inHole = true; }
            else if (u) inHole = false;
        }
        return h;
    }

    static int liveCount(boolean[] used) {
        int n = 0; for (boolean u : used) if (u) n++; return n;
    }

    public static void main(String[] args) {
        // 初始：12 槽，标记为 '#'=存活(1..6, 8..10)，'.'=垃圾
        String layout = "######.##..##";
        boolean[] used = new boolean[SLOTS];
        for (int i = 0; i < SLOTS; i++) used[i] = layout.charAt(i) == '#';
        System.out.println("before GC       : " + layout + "   live=" + liveCount(used)
                + " holes=" + holes(used));

        // ① 标记-清除：清除垃圾，不移动 -> 空洞保留
        boolean[] m = used.clone();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < SLOTS; i++) sb.append(m[i] ? '#' : '.');
        System.out.println("mark-sweep      : " + sb + "   live=" + liveCount(m)
                + " moves=0 holes=" + holes(m));

        // ② 标记-整理：存活对象向一端滑动，填掉空洞
        int w = 0; String[] arr = layout.split("");
        String[] comp = new String[SLOTS];
        Arrays.fill(comp, ".");
        int moves = 0;
        for (int i = 0; i < SLOTS; i++) {
            if (used[i]) { comp[w] = "#"; if (w != i) moves++; w++; }
        }
        System.out.println("mark-compact    : " + String.join("", comp) + "   live=" + w
                + " moves=" + moves + " holes=" + holes(toBool(comp)));

        // ③ 复制：两半空间，存活对象复制到另一半
        int half = SLOTS / 2;
        int liveInFirst = 0;
        for (int i = 0; i < half; i++) if (used[i]) liveInFirst++;
        System.out.println("copy(2 halves)  : half=" + half + " liveInFirstHalf=" + liveInFirst
                + " -> wasteful if semispace not full");
        System.out.println("copy moves = live count   : " + liveCount(used)
                + " (every live object moves)");
        System.out.println("trade-off: sweep keeps holes, compact moves but is fragment-free,"
                + " copy wastes half the space");
    }

    static boolean[] toBool(String[] a) {
        boolean[] r = new boolean[a.length];
        for (int i = 0; i < a.length; i++) r[i] = a[i].equals("#");
        return r;
    }
}
